const PLACE_DETAILS = {
 'edimburgo':{title:'Edimburgo',country:'Escocia',day:1,lead:'Una capital construida sobre un relieve extraordinario, donde la ciudad medieval y la ciudad georgiana conviven a ambos lados de un antiguo valle.',sections:[
  ['Una ciudad que se entiende desde el terreno','Edimburgo no se desarrolló sobre una llanura. La Old Town ocupa una cresta rocosa que desciende desde Castle Rock hacia Holyrood, mientras que al norte se abre la depresión donde estuvo el Nor Loch. Esta topografía condicionó las calles, las defensas y hasta la forma de crecer de la ciudad. Por eso la Royal Mile actúa como una auténtica espina dorsal: desde ella parten closes y wynds que bajan por las laderas.'],
  ['De burgo medieval a capital ilustrada','La ciudad creció alrededor de la fortaleza y de la corte real. Durante siglos la población se concentró en un espacio muy reducido, con edificios altos y calles estrechas. En el siglo XVIII, la creación de la New Town cambió por completo la escala urbana. Sus calles rectas, plazas y fachadas georgianas reflejan la confianza de la Ilustración escocesa y contrastan con la densidad de la ciudad medieval.'],
  ['La Ilustración escocesa','Edimburgo fue uno de los grandes centros intelectuales europeos del siglo XVIII. David Hume, Adam Smith, James Hutton y otros pensadores participaron en un ambiente de debate que dejó huella en filosofía, economía, ciencia y medicina. Esa tradición explica la importancia de instituciones como la universidad, los museos y las sociedades científicas.'],
  ['Qué merece la pena observar','Más que intentar completar una lista de monumentos, conviene mirar cómo se relacionan el castillo, la Royal Mile, los jardines y la New Town. Desde un punto elevado se entiende enseguida que las distintas etapas históricas de Edimburgo están escritas sobre el propio relieve.']
 ]},
 'castillo-de-edimburgo':{title:'Castillo de Edimburgo',country:'Escocia',day:1,lead:'Fortaleza, residencia real y símbolo nacional sobre Castle Rock.',sections:[
  ['Castle Rock','La roca del castillo es el resto resistente de un antiguo complejo volcánico. La erosión y los glaciares eliminaron materiales más blandos y dejaron una posición abrupta por tres lados, con un acceso más fácil desde el este. Esa combinación explica por qué el lugar tuvo un valor defensivo excepcional.'],
  ['Una fortaleza de muchas épocas','El conjunto no responde a un único proyecto. La capilla de Santa Margarita, del siglo XII, es el edificio conservado más antiguo; el Great Hall recuerda la etapa cortesana y real; y baterías, cuarteles y prisiones muestran el uso militar posterior. Recorrer el castillo es recorrer siglos de transformaciones.'],
  ['Las Honours of Scotland y la Stone of Destiny','Las joyas de la Corona escocesa se cuentan entre las insignias reales más antiguas conservadas en Europa. Junto a ellas se muestra la Stone of Destiny, vinculada durante siglos a las ceremonias de coronación de los reyes de Escocia.'],
  ['Qué no perderse','Crown Square, la capilla de Santa Margarita, el Great Hall y las vistas sobre la ciudad justifican la visita incluso si alguna de las zonas interiores tiene cola.']
 ]},
 'glen-coe':{title:'Glen Coe',country:'Escocia',day:2,lead:'Uno de los paisajes más poderosos de las Highlands y un lugar donde geología e historia se superponen.',sections:[
  ['Un valle modelado por el hielo','Las rocas de Glen Coe se relacionan con una actividad volcánica muy antigua, pero la forma actual del valle se debe sobre todo a los glaciares. El hielo ensanchó el fondo, recortó las laderas y dejó el perfil en U que se reconoce desde la carretera. Las Three Sisters y Buachaille Etive Mòr son algunas de las referencias visuales más conocidas.'],
  ['La matanza de 1692','Glen Coe está asociado a un episodio especialmente oscuro de la historia escocesa. Soldados del Gobierno fueron alojados por los MacDonald durante casi dos semanas y recibieron después la orden de atacar a sus anfitriones. Murieron decenas de personas y otras fallecieron al huir durante el invierno. La memoria del suceso permanece ligada al valle por la ruptura de las normas tradicionales de hospitalidad.'],
  ['Cómo disfrutar la parada','No hace falta caminar grandes distancias. Desde los miradores de carretera se aprecia bien la escala del paisaje. Merece la pena observar el fondo relativamente abierto del valle y las laderas que ascienden con brusquedad: son las huellas más claras de su origen glaciar.']
 ]},
 'lago-ness':{title:'Lago Ness',country:'Escocia',day:2,lead:'Un lago célebre por Nessie, pero geológicamente mucho más interesante de lo que su leyenda sugiere.',sections:[
  ['El Great Glen','Loch Ness forma parte del Great Glen, una gran línea de fractura que atraviesa Escocia de suroeste a nordeste. Los glaciares aprovecharon esa debilidad de la corteza y profundizaron el valle, creando una cadena de lagos largos y estrechos.'],
  ['Agua oscura y gran profundidad','El color oscuro del agua se debe en parte a materia orgánica procedente de las turberas. Esa apariencia, combinada con la profundidad del lago y la frecuencia de nieblas, ha contribuido a la atmósfera que rodea las historias sobre el monstruo.'],
  ['Nessie','Los relatos modernos sobre una criatura en el lago adquirieron fama internacional en el siglo XX. No existe evidencia científica que demuestre la presencia de un gran animal desconocido, pero la leyenda se ha convertido en parte inseparable de la cultura popular de las Highlands.']
 ]},
 'dunnottar':{title:'Castillo de Dunnottar',country:'Escocia',day:3,lead:'Una fortaleza espectacular cuyo verdadero sistema defensivo era el propio promontorio.',sections:[
  ['Una posición casi inexpugnable','El castillo ocupa una plataforma rocosa rodeada de acantilados y conectada con tierra por un acceso estrecho. Esa geometría permitía defender el lugar con relativamente pocos hombres. La imagen actual es fruto de siglos de reformas y reúne edificios militares, residenciales y de servicio.'],
  ['Las joyas de la Corona','En el siglo XVII, durante la campaña de Oliver Cromwell, las Honours of Scotland fueron llevadas a Dunnottar para impedir su captura. Tras un prolongado asedio, lograron sacarse y ocultarse hasta la restauración de la monarquía. El episodio reforzó el papel simbólico del castillo en la historia nacional.'],
  ['Antes de bajar','El acceso interior implica bastantes escalones. Incluso quien no entre debería caminar hasta el primer mirador: es allí donde se comprende la relación entre la fortaleza, el istmo y el Mar del Norte.']
 ]},
 'saint-andrews':{title:'Saint Andrews',country:'Escocia',day:3,lead:'Una pequeña ciudad con tres identidades extraordinarias: religión, universidad y golf.',sections:[
  ['Capital religiosa medieval','Durante la Edad Media, Saint Andrews fue el principal centro eclesiástico de Escocia. La gran catedral fue lugar de peregrinación y una de las instituciones religiosas más poderosas del reino. Sus ruinas permiten imaginar la escala que tuvo antes de la Reforma del siglo XVI.'],
  ['La universidad','Fundada a comienzos del siglo XV, la University of St Andrews es la más antigua de Escocia. No forma un campus aislado: colegios, patios y edificios académicos están integrados en el casco urbano, algo que explica el ambiente de la ciudad.'],
  ['La cuna del golf','Los links costeros de Saint Andrews están vinculados a los orígenes y a la codificación del golf moderno. El Old Course se desarrolló sobre dunas y terrenos naturales junto al mar. El pequeño Swilcan Bridge, cerca del hoyo 18, es una de las imágenes más reconocibles del deporte.']
 ]},
 'anillo-de-kerry':{title:'Anillo de Kerry',country:'Irlanda',day:5,lead:'Una ruta panorámica donde el paisaje, y no un monumento concreto, es el verdadero protagonista.',sections:[
  ['La península de Iveragh','El recorrido atraviesa una península montañosa y muy recortada por el Atlántico. Los glaciares modelaron valles y cubetas lacustres, mientras el mar y los ríos terminaron de dibujar playas, cabos y ensenadas.'],
  ['Killarney y Ladies View','Los lagos de Killarney, los bosques y las montañas forman uno de los paisajes clásicos de Irlanda. Desde Ladies View se percibe con claridad la sucesión de lagos y relieves. El nombre se relaciona tradicionalmente con las damas de compañía de la reina Victoria durante su visita de 1861.'],
  ['La carretera como parte de la visita','En Kerry no tiene sentido medir el éxito por el número de paradas. La luz cambia con rapidez y cada curva ofrece una relación distinta entre montaña y mar. Para un grupo grande resulta mucho más agradable elegir pocos miradores y detenerse con tiempo.']
 ]},
 'cobh':{title:'Cobh',country:'Irlanda',day:6,lead:'Un puerto de casas de colores cuya historia está marcada por la emigración y las despedidas.',sections:[
  ['La puerta de salida de Irlanda','Durante los siglos XIX y XX, Cobh fue uno de los principales puertos de salida de emigrantes irlandeses. La Gran Hambruna aceleró un proceso que continuó durante generaciones. Para muchas familias, este puerto fue la última imagen de Irlanda antes de partir hacia Gran Bretaña, Norteamérica o Australia.'],
  ['Queenstown y el Titanic','Entre 1849 y 1920 la ciudad se llamó Queenstown. El 11 de abril de 1912, el Titanic hizo aquí su última escala antes de cruzar el Atlántico. El buque permaneció fondeado y los pasajeros llegaron hasta él en embarcaciones auxiliares. La historia del Titanic es famosa, pero es solo una parte de la memoria marítima de Cobh.'],
  ['St Colman y la imagen del puerto','La catedral de St Colman domina la ladera y sirve de referencia desde la bahía. La combinación de pendientes, fachadas de colores y el gran edificio neogótico explica la imagen más conocida de la localidad.']
 ]},
 'blarney-castle':{title:'Blarney Castle & Gardens',country:'Irlanda',day:6,lead:'Mucho más que la famosa piedra: una casa-torre gaélica rodeada de jardines y leyendas.',sections:[
  ['Los MacCarthy','La gran torre fue construida en el siglo XV por los MacCarthy de Muskerry. Como otras casas-torre irlandesas, combinaba funciones residenciales, defensivas y representativas. Las escaleras estrechas y los espacios compactos recuerdan que la seguridad importaba tanto como la comodidad.'],
  ['La Piedra de Blarney','La tradición afirma que quien besa la piedra recibe el don de la elocuencia. Existen varias leyendas sobre su origen y ninguna explicación histórica definitiva. Conviene entender el beso como un rito popular que ha acabado formando parte de la identidad turística del castillo.'],
  ['Los jardines','Rock Close, los senderos, los cursos de agua y los árboles maduros permiten una visita muy diferente a la subida a la torre. Son especialmente útiles para quienes prefieran evitar escaleras o colas.']
 ]},
 'galway':{title:'Galway',country:'Irlanda',day:7,lead:'Una ciudad atlántica que se disfruta tanto por su ambiente como por sus monumentos.',sections:[
  ['Puerto medieval y Tribes of Galway','Galway prosperó como puerto comercial y mantuvo relaciones con Gran Bretaña y la Europa atlántica. Durante siglos, varias familias mercantiles dominaron la vida urbana y fueron conocidas como las Tribes of Galway. El casco histórico conserva la escala compacta de aquella ciudad comercial.'],
  ['Spanish Arch y Claddagh','El Spanish Arch formaba parte de las defensas junto a los muelles y su nombre recuerda la tradición comercial con la península ibérica. Al otro lado del Corrib se encontraba Claddagh, antiguo barrio pesquero asociado al conocido anillo de manos, corazón y corona.'],
  ['Música y vida en la calle','Shop Street y Quay Street concentran músicos, pubs, pequeños comercios y restaurantes. Galway se entiende mejor dejando algo de tiempo libre que intentando seguir una lista rígida de visitas.']
 ]},
 'el-burren':{title:'El Burren',country:'Irlanda',day:7,lead:'Un paisaje calizo aparentemente desnudo que esconde una extraordinaria diversidad natural y una larga presencia humana.',sections:[
  ['Un paisaje kárstico','La superficie está formada por grandes losas de caliza separadas por grietas. El agua se infiltra con rapidez y circula bajo tierra, creando cavidades, cuevas y conductos. Esa falta de agua superficial contribuye a la apariencia austera del territorio.'],
  ['Una flora inesperada','En las grietas protegidas crecen especies que normalmente asociaríamos a regiones muy diferentes. Plantas atlánticas, alpinas y mediterráneas pueden encontrarse muy próximas entre sí gracias a la combinación de microclimas, roca caliza y prácticas ganaderas tradicionales.'],
  ['Paisaje cultural','Muros de piedra seca, restos arqueológicos y pequeñas explotaciones recuerdan que el Burren no es un espacio vacío. Las comunidades humanas se han adaptado durante milenios a un suelo que a primera vista parece poco favorable.']
 ]},
 'acantilados-de-moher':{title:'Acantilados de Moher',country:'Irlanda',day:7,lead:'Una pared de roca frente al Atlántico donde la geología, el viento y las aves forman una sola experiencia.',sections:[
  ['Cómo se formaron','Los acantilados están compuestos por capas de areniscas, limos y lutitas depositadas hace cientos de millones de años. La erosión marina socava la base y abre fracturas; los desprendimientos resultantes mantienen el frente abrupto.'],
  ['Una colonia de aves marinas','Los cortados ofrecen lugares de nidificación inaccesibles para muchos depredadores. En temporada pueden verse fulmares, araos, alcas y, con algo de suerte, frailecillos. Unos pequeños prismáticos ayudan mucho más que acercarse al borde.'],
  ['La experiencia depende del tiempo','Sol, lluvia, niebla y viento cambian por completo la percepción del lugar. La roca puede pasar del ocre al gris casi negro en minutos. No hace falta un cielo despejado para disfrutar de Moher: el mal tiempo puede intensificar su carácter atlántico.']
 ]},
 'dublin':{title:'Dublín',country:'Irlanda',day:8,lead:'Una capital compacta, literaria y atravesada por capas de historia vikinga, medieval, británica e independiente.',sections:[
  ['De Dubh Linn a la capital','La ciudad creció a partir de asentamientos gaélicos y vikingos junto al Liffey. El nombre inglés procede de Dubh Linn, “laguna negra”, mientras que Baile Átha Cliath, el nombre irlandés, recuerda un antiguo vado. Su posición portuaria convirtió a Dublín en centro político y comercial.'],
  ['Christ Church y Dublin Castle','Christ Church conserva la memoria de la ciudad medieval. Muy cerca, Dublin Castle fue durante siglos la sede del poder inglés y posteriormente británico en Irlanda. Caminar entre ambos permite recorrer, en pocos minutos, buena parte de la historia institucional de la capital.'],
  ['Una ciudad literaria','Swift, Wilde, Yeats, Joyce y Beckett son solo algunos de los escritores ligados a Dublín. La literatura está presente en bibliotecas, teatros, pubs y en la propia imagen cultural de la ciudad. Incluso en una visita breve conviene recordar que su prestigio no depende únicamente de los monumentos.'],
  ['Temple Bar con perspectiva','El barrio es conocido por los pubs, pero también concentra espacios culturales y una trama de calles que merece recorrerse antes de que se llene. A primera hora ofrece una impresión mucho más tranquila.']
 ]}
};

function slugify(s){return s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/&/g,'y').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
function routeLink(n){const r=ROUTES[n]; if(!r) return null; const p=r.points; const origin=p[0], destination=p[p.length-1], waypoints=p.slice(1,-1).join('|'); return `https://www.google.com/maps/dir/?api=1&origin=${encodeURIComponent(origin)}&destination=${encodeURIComponent(destination)}${waypoints?`&waypoints=${encodeURIComponent(waypoints)}`:''}&travelmode=${r.mode}`;}
function detailFor(name){return PLACE_DETAILS[slugify(name)] || null;}

function mapsLink(q){return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(q)}`}
function todayNumber(){const now=new Date(); if(now.getFullYear()!==2026||now.getMonth()!==7) return null; const d=now.getDate(); return d>=13&&d<=20?d-12:null;}
function dayCard(d){const today=todayNumber()===d.n?' today':'';return `<a class="card day-card${today}" href="#dia-${d.n}"><div class="day-number">Día ${d.n} · ${d.date}</div><h3>${d.title}</h3><p>${d.subtitle}</p><div class="badges">${d.tags.map(t=>`<span class="badge">${t}</span>`).join('')}</div></a>`}
function renderHome(){const t=todayNumber(),hero=PHOTOS[1];return `<section class="hero hero-photo" id="inicio" style="--hero-image:url('${hero.url}')"><div class="hero-inner"><div class="eyebrow">13–20 agosto 2026 · 23 viajeros</div><h1>Escocia e Irlanda en familia</h1><p>Guía digital con itinerario, contexto, hoteles, mapas y datos prácticos para consultar durante el viaje.</p><div class="hero-actions"><a class="btn" href="#dias">Ver los 8 días</a><a class="btn secondary" href="#historia">Historia y contexto</a></div><div class="stats"><div class="stat"><strong>8</strong><span>días</span></div><div class="stat"><strong>2</strong><span>países</span></div><div class="stat"><strong>23</strong><span>viajeros</span></div><div class="stat"><strong>5</strong><span>coches en Irlanda</span></div></div><div class="photo-credit"><a href="${hero.source}" target="_blank">Foto: ${hero.credit}</a></div></div></section>${t?`<section class="container"><div class="today-panel"><div class="card today-main"><div class="eyebrow">Hoy toca</div><h2>Día ${t} · ${DAYS[t-1].title}</h2><p>${DAYS[t-1].summary}</p><a class="btn secondary" href="#dia-${t}">Abrir jornada</a></div><div class="card today-side"><div><div class="day-number">Dormimos en</div><div class="big">${DAYS[t-1].sleep}</div></div><div class="muted">${DAYS[t-1].date}</div></div></div></section>`:''}<section class="container"><div class="section-title"><div><div class="eyebrow" style="color:var(--accent-2)">Mapa general</div><h2>La ruta completa</h2></div><p>Mapa interactivo orientativo de Escocia e Irlanda.</p></div><div class="map-card"><div id="tripMap" class="map"></div></div></section><section class="container" id="dias"><div class="section-title"><div><div class="eyebrow" style="color:var(--accent-2)">Itinerario</div><h2>El viaje de un vistazo</h2></div><p>Toca cualquier jornada para abrir horarios, lugares, contexto y recomendaciones.</p></div><div class="grid">${DAYS.map(dayCard).join('')}</div></section><section class="container home-links"><div class="grid"><a class="card feature-link" href="#historia"><div class="day-number">Antes de viajar</div><h3>Historia de Escocia e Irlanda</h3><p>Dos introducciones pensadas para entender mejor lo que iremos viendo.</p></a><a class="card feature-link" href="#lugares"><div class="day-number">Lectura</div><h3>Lugares del viaje</h3><p>Fichas ampliadas para leer antes de cada parada.</p></a><a class="card feature-link" href="#hoteles"><div class="day-number">Alojamiento</div><h3>Hoteles y datos de contacto</h3><p>Direcciones, teléfonos, noches y acceso rápido a Google Maps.</p></a></div></section>`}
function renderDay(n){
 const d=DAYS.find(x=>x.n===n)||DAYS[0],ph=PHOTOS[d.n],route=routeLink(d.n);
 return `<section class="day-hero day-photo" style="--day-image:url('${ph.url}')"><div class="container"><a class="back" href="#dias">← Todos los días</a><div class="eyebrow">Día ${d.n} · ${d.date} · Noche: ${d.sleep}</div><h1>${d.title}</h1><p>${d.subtitle}</p><div class="day-progress"><span style="width:${d.n/8*100}%"></span></div><div class="photo-credit"><a href="${ph.source}" target="_blank">Foto: ${ph.credit}</a></div></div></section><section class="container"><div class="card"><h2>Resumen del día</h2><p>${d.summary}</p></div><div class="section-title"><div><div class="eyebrow" style="color:var(--accent-2)">Ruta</div><h2>Mapa de la jornada</h2></div><p>Marcadores orientativos de las principales paradas.</p></div><div class="map-card"><div id="dayMap" class="map day-map"></div></div>${route?`<div class="actions route-actions"><a class="btn" target="_blank" rel="noopener" href="${route}">🧭 Abrir ruta del día en Google Maps</a></div>`:`<div class="callout compact"><strong>Ruta del día</strong>Este día combina desplazamientos urbanos, traslado al aeropuerto y vuelo; no se representa como una única ruta de carretera.</div>`}<div class="section-title"><h2>Horario</h2></div><div class="card schedule">${d.schedule.map(r=>`<div class="schedule-row"><div class="time">${r[0]}</div><div>${r[1]}</div></div>`).join('')}</div><div class="section-title"><div><h2>Lugares</h2></div><p>Resumen para la jornada. Las fichas ampliadas permiten leer con más calma antes de llegar.</p></div>${d.places.map(p=>{const det=detailFor(p[0]);return `<article class="card place"><h3>${p[0]}</h3><p>${p[1]}</p><div class="actions">${det?`<a class="btn" href="#lugar-${slugify(p[0])}">Leer más →</a>`:''}<a class="btn secondary" target="_blank" rel="noopener" href="${mapsLink(p[0])}">📍 Abrir en Maps</a></div></article>`}).join('')}<div class="callout"><strong>Cinco minutos antes de llegar</strong>${d.before}</div><div class="callout"><strong>Si solo pudiera recomendar una cosa de hoy…</strong>${d.recommend}</div><div class="actions"><a class="btn secondary" href="#dia-${Math.max(1,n-1)}">← Día anterior</a><a class="btn" href="#dia-${Math.min(8,n+1)}">Día siguiente →</a></div></section>`
}
function renderPlaces(){const entries=Object.entries(PLACE_DETAILS);return `<section class="page-head"><div class="container"><div class="eyebrow">Para leer antes de llegar</div><h1>Lugares del viaje</h1><p>Fichas más amplias para quienes quieran conocer la historia, el paisaje y el contexto de cada parada.</p></div></section><section class="container"><div class="places-index">${entries.map(([slug,p])=>`<a class="card place-index-card" href="#lugar-${slug}"><div class="day-number">${p.country} · Día ${p.day}</div><h3>${p.title}</h3><p>${p.lead}</p><span class="text-link">Leer ficha →</span></a>`).join('')}</div></section>`}
function renderPlace(slug){const p=PLACE_DETAILS[slug]; if(!p)return renderPlaces(); return `<section class="page-head place-head"><div class="container"><a class="back" href="#dia-${p.day}">← Volver al Día ${p.day}</a><div class="eyebrow">${p.country} · Día ${p.day}</div><h1>${p.title}</h1><p>${p.lead}</p><div class="actions"><a class="btn" target="_blank" rel="noopener" href="${mapsLink(p.title)}">📍 Abrir en Maps</a></div></div></section><section class="container reading">${p.sections.map(s=>`<article class="card reading-section"><h2>${s[0]}</h2><p>${s[1]}</p></article>`).join('')}<div class="actions"><a class="btn secondary" href="#dia-${p.day}">← Volver a la jornada</a><a class="btn" href="#lugares">Todas las fichas</a></div></section>`}
function historyBlock(key){const h=HISTORY[key];return `<article class="history-block"><div class="day-number">${key==='scotland'?'Escocia':'Irlanda'}</div><h2>${h.title}</h2><p class="history-intro">${h.intro}</p>${h.sections.map(s=>`<section class="card history-section"><h3>${s[0]}</h3><p>${s[1]}</p></section>`).join('')}</article>`}
function renderHistory(){return `<section class="page-head"><div class="container"><div class="eyebrow">Contexto</div><h1>Historia para entender el viaje</h1><p>No es un manual de historia: son las claves necesarias para que castillos, ciudades y paisajes tengan más sentido cuando estemos allí.</p></div></section><section class="container history-wrap">${historyBlock('scotland')}${historyBlock('ireland')}</section>`}
function renderHotels(){return `<section class="page-head"><div class="container"><div class="eyebrow">Alojamiento</div><h1>Hoteles</h1><p>Información de consulta rápida durante el viaje.</p></div></section><section class="container" id="hoteles"><div class="grid">${HOTELS.map(h=>`<article class="card hotel-card"><div class="day-number">${h.city}</div><h3>${h.name}</h3><div class="hotel-meta"><div>${h.address}</div><div><strong>Noches:</strong> ${h.nights}</div>${h.phone?`<div><strong>Tel.</strong> ${h.phone}</div>`:''}${h.email?`<div><strong>Email.</strong> ${h.email}</div>`:''}<div class="hotel-note">${h.note}</div></div><div class="actions"><a class="btn" target="_blank" rel="noopener" href="${mapsLink(h.name+' '+h.address)}">📍 Maps</a>${h.phone?`<a class="btn secondary" href="tel:${h.phone.replace(/\s/g,'')}">☎ Llamar</a>`:''}</div></article>`).join('')}</div></section>`}
function renderPractical(){return `<section class="page-head"><div class="container"><div class="eyebrow">Consulta rápida</div><h1>Información práctica</h1><p>Lo esencial para tener a mano sin abrir el documento Word.</p></div></section><section class="container" id="practico"><div class="quick-list">${practical.map(p=>`<div class="quick-item"><strong>${p[0]}</strong><div class="muted">${p[1]}</div></div>`).join('')}</div></section>`}
function baseMap(id){if(typeof L==='undefined')return null;return L.map(id,{scrollWheelZoom:false})}
function addTiles(m){L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(m)}
function initTripMap(){const el=document.getElementById('tripMap');if(!el||el._leaflet_id)return;const m=baseMap('tripMap');if(!m)return;addTiles(m);const pts=[[55.9533,-3.1883],[56.6826,-5.1023],[57.4778,-4.2247],[56.945,-2.197],[56.3398,-2.7967],[51.8985,-8.4756],[51.9668,-9.5931],[51.8507,-8.294],[53.2707,-9.0568],[52.9715,-9.4309],[53.3498,-6.2603]];L.polyline(pts,{color:'#b88b4a',weight:3,opacity:.8,dashArray:'8 8'}).addTo(m);[['Edimburgo',55.9533,-3.1883],['Cork',51.8985,-8.4756],['Galway',53.2707,-9.0568],['Dublín',53.3498,-6.2603]].forEach(p=>L.marker([p[1],p[2]]).addTo(m).bindPopup(`<strong>${p[0]}</strong>`));m.fitBounds(pts,{padding:[25,25]})}
function initDayMap(n){const el=document.getElementById('dayMap');if(!el||el._leaflet_id)return;const data=DAY_POINTS[n]||[],m=baseMap('dayMap');if(!m)return;addTiles(m);const pts=data.map(p=>[p[1],p[2]]);L.polyline(pts,{color:'#b88b4a',weight:4,opacity:.9}).addTo(m);data.forEach((p,i)=>L.marker([p[1],p[2]]).addTo(m).bindPopup(`<strong>${i+1}. ${p[0]}</strong>`));m.fitBounds(pts,{padding:[25,25]})}
function renderCredits(){const uniq=Object.values(PHOTOS).filter((x,i,a)=>a.findIndex(y=>y.source===x.source)===i);return `<section class="page-head"><div class="container"><div class="eyebrow">Imágenes y cartografía</div><h1>Créditos</h1><p>Fotografías de Wikimedia Commons y mapas de OpenStreetMap.</p></div></section><section class="container"><div class="grid">${uniq.map(p=>`<article class="card credit-card"><img src="${p.url}" alt="${p.caption}" loading="lazy"><h3>${p.caption}</h3><p class="muted">${p.credit}</p><a class="btn secondary" target="_blank" href="${p.source}">Ver ficha y licencia</a></article>`).join('')}</div><div class="callout"><strong>Cartografía</strong>Leaflet + OpenStreetMap. Las líneas de ruta son orientativas; para navegación real, usar Google Maps.</div></section>`}
function router(){let h=location.hash||'#inicio';document.getElementById('mainNav').classList.remove('open');if(h.startsWith('#dia-')){const n=Number(h.split('-')[1]);document.getElementById('app').innerHTML=renderDay(n);setTimeout(()=>initDayMap(n),50);}else if(h==='#dias'){document.getElementById('app').innerHTML=renderHome();setTimeout(()=>{initTripMap();document.getElementById('dias')?.scrollIntoView();},50);}else if(h.startsWith('#lugar-')){document.getElementById('app').innerHTML=renderPlace(h.slice(7));}else if(h==='#lugares'){document.getElementById('app').innerHTML=renderPlaces();}else if(h==='#historia'){document.getElementById('app').innerHTML=renderHistory();}else if(h==='#hoteles'){document.getElementById('app').innerHTML=renderHotels();}else if(h==='#practico'){document.getElementById('app').innerHTML=renderPractical();}else if(h==='#creditos'){document.getElementById('app').innerHTML=renderCredits();}else{document.getElementById('app').innerHTML=renderHome();setTimeout(initTripMap,50);}window.scrollTo(0,0)}
document.getElementById('menuBtn').addEventListener('click',()=>document.getElementById('mainNav').classList.toggle('open'));
window.addEventListener('hashchange',router);router();